using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
            string copy = "ArtReview/Characters/Canonical/active-scene-verification.unity";
            bool saved = UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene, copy, true);
            result.Log("Diagnostic copy saved=" + saved + "; original scene dirty=" + scene.isDirty);
        }
    }
}
